  if p_package_price is null or p_package_price <= 0 then raise exception 'INVALID_AMOUNT'; end if;
  if nullif(trim(coalesce(p_package_name, '')), '') is null then raise exception 'PACKAGE_NAME_REQUIRED'; end if;

