        'LOCATION_DENIED',
        'Location request declined',
        coalesce(v_owner_name, 'They') || ' didn''t approve your location request',
        '/u/' || v_uid,
        jsonb_build_object(
          'avatarUrl', v_owner_avatar,
          'actorName', v_owner_name,
          'ownerUserId', v_uid,
          'statusPill', 'Declined',
          'tone', 'neutral',
          'actions', jsonb_build_array()
        )
      );
